const body = $input.item.json.body || $input.item.json;

const name = (body.name || '').trim();
const email = (body.email || '').trim().toLowerCase();
const service = (body.service || 'autre').trim();
const message = (body.message || '').trim();
const date = body.date || new Date().toISOString();
const source = body.source || 'netroia.tech';
const ip = ($input.item.json.headers && $input.item.json.headers['x-forwarded-for']) || 'unknown';

// Validation minimale
if (!name || name.length < 2) throw new Error('Champ name invalide ou manquant');
if (!email || !email.includes('@')) throw new Error('Champ email invalide ou manquant');
if (!message || message.length < 10) throw new Error('Champ message trop court');

return [{
  json: { name, email, service, message, date, source, ip }
}];

